import java.util.*;

class Solution {
    public List<Double> windowMedians(int[] nums, int k) {
        // order indices by value, then by index so equal values stay distinct
        Comparator<Integer> cmp = (a, b) -> nums[a] != nums[b] ? Integer.compare(nums[a], nums[b]) : Integer.compare(a, b);
        TreeSet<Integer> low = new TreeSet<>(cmp), high = new TreeSet<>(cmp);
        List<Double> res = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            low.add(i);
            high.add(low.pollLast());                    // largest of low moves up
            if (i >= k) {                                // remove the index leaving the window
                if (!low.remove(i - k)) high.remove(i - k);
            }
            while (high.size() > low.size()) low.add(high.pollFirst());
            while (low.size() > high.size() + 1) high.add(low.pollLast());
            if (i >= k - 1) {
                if (k % 2 == 1) res.add((double) nums[low.last()]);
                else res.add(((long) nums[low.last()] + nums[high.first()]) / 2.0);
            }
        }
        return res;
    }
}

